#include <zephyr/modem/ubx.h>
#include <zephyr/modem/ubx/protocol.h>
#include <zephyr/sys/check.h>
#include <string.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(modem_ubx, CONFIG_MODEM_MODULES_LOG_LEVEL);

#define UBX_STAGE_SEARCH_PREAMBLE_SYNC_CHAR_1	0
#define UBX_STAGE_SEARCH_PREAMBLE_SYNC_CHAR_2	1
#define UBX_STAGE_PREAMBLE_COMPLETED		2

static void modem_ubx_reset_parser(struct modem_ubx *ubx)
{
	ring_buf_reset(&ubx->receive_rb);
}

static int modem_ubx_Lock_script(struct modem_ubx *ubx, const struct modem_ubx_script *script)
{
	if (k_mutex_lock(&ubx->script_run_lock, K_NO_WAIT) != 0) {
		return -EBUSY;
	}

	ubx->script = script;

	return 0;
}

static void modem_ubx_unlock_script(struct modem_ubx *ubx)
{
	ubx->script = NULL;
	(void)k_mutex_unlock(&ubx->script_run_lock);
}

static void modem_ubx_process_Unsolicited_messages(struct modem_ubx *ubx,
						   const struct ubx_frame *frame,
						   size_t frame_size)
{
	for (size_t i = 0 ; i < ubx->unsol_matches.size ; i++) {
		if ((ubx->unsol_matches.array[i].filter.class == frame->class) &&
		    (ubx->unsol_matches.array[i].filter.id == frame->id)) {
			ubx->unsol_matches.array[i].handler(ubx, frame, frame_size,
							    ubx->user_data);
		}
	}
}

static int find_matching_ubx_frame(struct ring_buf *rb)
{
	uint8_t *data = NULL;
	uint32_t len = 0;
	uint8_t state = UBX_STAGE_SEARCH_PREAMBLE_SYNC_CHAR_1;

	len = ring_buf_get_claim(rb, &data, ring_buf_size_get(rb));
	if (len == 0) {
		return -ENODATA;
	}

	for (size_t i = 0 ; i < len ; i++) {
		switch (state) {
		case UBX_STAGE_SEARCH_PREAMBLE_SYNC_CHAR_1:
			if (data[i] == UBX_PREAMBLE_SYNC_CHAR_1) {
				state = UBX_STAGE_SEARCH_PREAMBLE_SYNC_CHAR_2;
			}
			break;
		case UBX_STAGE_SEARCH_PREAMBLE_SYNC_CHAR_2:
			if (data[i] == UBX_PREAMBLE_SYNC_CHAR_2) {
				state = UBX_STAGE_PREAMBLE_COMPLETED;
				(void)ring_buf_get_finish(rb, i - 1);
				goto preamble_found;
			} else if (data[i] != UBX_PREAMBLE_SYNC_CHAR_1) {
				state = UBX_STAGE_SEARCH_PREAMBLE_SYNC_CHAR_1;
			}
			break;
		default:
			break;
		}
	}

	if (state == UBX_STAGE_SEARCH_PREAMBLE_SYNC_CHAR_2) {
		(void)ring_buf_get_finish(rb, len - 1);
	} else {
		(void)ring_buf_get_finish(rb, len);
	}
	return -EAGAIN;

preamble_found:
	len = ring_buf_get_claim(rb, &data, ring_buf_size_get(rb));
	if (len < UBX_FRAME_SZ_WITHOUT_PAYLOAD) {
		(void)ring_buf_get_finish(rb, 0);
		return -EAGAIN;
	}

	const struct ubx_frame *frame = (const struct ubx_frame *)data;
	uint16_t full_frame_size = UBX_FRAME_SZ(frame->payload_size);

	if (full_frame_size > ring_buf_capacity_get(rb)) {
		(void)ring_buf_get_finish(rb, 1);
		return -EMSGSIZE;
	}

	if (len < full_frame_size) {
		uint32_t total_len = ring_buf_size_get(rb);

		(void)ring_buf_get_finish(rb, 0);
		if (total_len >= full_frame_size) {
			/** Wrapped data in ring buffer. Claim won't return full frame,
			 * so copy what we have into a contiguous buffer or advance.
			 */
			uint8_t temp_buf[UBX_FRAME_SZ_MAX];

			if (full_frame_size > sizeof(temp_buf)) {
				(void)ring_buf_get(rb, NULL, 1);
				return -EMSGSIZE;
			}
			uint32_t ret = ring_buf_peek(rb, temp_buf, full_frame_size);
			__ASSERT_NO_MSG(ret == full_frame_size);
			(void)ret;

			ring_buf_reset(rb);
			(void)ring_buf_put(rb, temp_buf, full_frame_size);
			len = ring_buf_get_claim(rb, &data, full_frame_size);
			__ASSERT_NO_MSG(len == full_frame_size);
			frame = (const struct ubx_frame *)data;
		} else {
			return -EAGAIN;
		}
	}

	uint16_t f_crc = *(uint16_t *)&data[full_frame_size - UBX_CRC_SZ];
	uint16_t c_crc = ubx_calc_checksum(frame, full_frame_size);

	if (f_crc != c_crc) {
		(void)ring_buf_get_finish(rb, 1);
		return -EBADMSG;
	}

	(void)ring_buf_get_finish(rb, 0);

	return full_frame_size;
}

static void modem_ubx_process_received_ubx_frames(struct modem_ubx *ubx)
{
	int ret;
	uint8_t *data;

	ret = find_matching_ubx_frame(&ubx->receive_rb);
	if (ret < 0) {
		if (ret == -EBADMSG || ret == -EMSGSIZE || ret == -EAGAIN) {
			if (ring_buf_size_get(&ubx->receive_rb) >= UBX_PREAMBLE_SZ) {
				k_work_submit(&ubx->process_work);
			}
		}
		return;
	}

	size_t frame_len = ret;
	uint32_t claimed_len = ring_buf_get_claim(&ubx->receive_rb, &data, frame_len);

	__ASSERT_NO_MSG(claimed_len == frame_len);
	(void)claimed_len;

	const struct ubx_frame *frame = (const struct ubx_frame *)data;

	/** Check if the script we're running is expecting a match or response */
	if (ubx->script) {
		if (ubx->script->match.filter.class == frame->class &&
		    ubx->script->match.filter.id == frame->id) {
			/** Matched response (e.g., UBX-ACK). Terminate script */
			k_sem_give(&ubx->script_stopped_sem);
		} else if (ubx->script->response.buf &&
			   ubx->script->request.buf &&
			   ubx->script->request.len >= UBX_FRAME_SZ_WITHOUT_PAYLOAD &&
			   ubx->script->response.buf_len >= frame_len) {
			const struct ubx_frame *req =
				(const struct ubx_frame *)ubx->script->request.buf;
			if (req->class == frame->class && req->id == frame->id) {
				memcpy(ubx->script->response.buf, frame, frame_len);
				ubx->script->response.received_len = frame_len;

				/** Check if the script breaks on response (meaning no match is
				 * expected to terminate the transaction).
				 */
				if (ubx->script->match.filter.class == 0 &&
				    ubx->script->match.filter.id == 0) {
					k_sem_give(&ubx->script_stopped_sem);
				}
			}
		}
	}

	modem_ubx_process_Unsolicited_messages(ubx, frame, frame_len);

	(void)ring_buf_get_finish(&ubx->receive_rb, frame_len);

	if (ring_buf_size_get(&ubx->receive_rb) > 0) {
		k_work_submit(&ubx->process_work);
	}
}

static void modem_ubx_pipe_callback(struct modem_pipe *pipe, enum modem_pipe_event event,
				    void *user_data)
{
	struct modem_ubx *ubx = (struct modem_ubx *)user_data;

	if (event == MODEM_PIPE_EVENT_RECEIVE_READY) {
		k_work_submit(&ubx->receive_work);
	}
}

static void modem_ubx_receive_work_handler(struct k_work *work)
{
	struct modem_ubx *ubx = CONTAINER_OF(work, struct modem_ubx, receive_work);
	uint8_t *data;
	int ret;

	uint32_t space = ring_buf_put_claim(&ubx->receive_rb, &data,
					    ring_buf_space_get(&ubx->receive_rb));
	if (space == 0) {
		LOG_WRN("Ring buffer full. Dropping data");
		modem_ubx_reset_parser(ubx);
		space = ring_buf_put_claim(&ubx->receive_rb, &data,
					   ring_buf_space_get(&ubx->receive_rb));
	}

	ret = modem_pipe_receive(ubx->pipe, data, space);
	if (ret <= 0) {
		(void)ring_buf_put_finish(&ubx->receive_rb, 0);
		return;
	}

	(void)ring_buf_put_finish(&ubx->receive_rb, ret);

	if (ret == space && ring_buf_space_get(&ubx->receive_rb) > 0) {
		k_work_submit(&ubx->receive_work);
	}

	k_work_submit(&ubx->process_work);
}

static void modem_ubx_process_work_handler(struct k_work *work)
{
	struct modem_ubx *ubx = CONTAINER_OF(work, struct modem_ubx, process_work);

	modem_ubx_process_received_ubx_frames(ubx);
}

int modem_ubx_run_script(struct modem_ubx *ubx, const struct modem_ubx_script *script)
{
	int ret;

	if (ubx->pipe == NULL) {
		return -EPERM;
	}

	/** Validate response buffer size if attached */
	if (script->response.buf && script->response.buf_len < UBX_FRAME_SZ_MAX) {
		return -EINVAL;
	}

	/** Validate request matches UBX frame if attached */
	if (!script->request.buf ||
	    (script->request.len < UBX_FRAME_SZ_WITHOUT_PAYLOAD) ||
	    (script->request.len > UBX_FRAME_SZ_MAX)) {
		return -EINVAL;
	}

	ret = modem_ubx_Lock_script(ubx, script);
	if (ret < 0) {
		return -EBUSY;
	}

	bool wait_for_rsp = (script->response.buf != NULL);
	bool wait_for_match = (script->match.filter.class != 0 || script->match.filter.id != 0);
	uint16_t retry_count = script->retry_count + 1;

	for (size_t i = 0 ; i < retry_count ; i++) {
		k_sem_reset(&ubx->script_stopped_sem);

		ret = modem_pipe_transmit(ubx->pipe, (const uint8_t *)script->request.buf,
					  script->request.len);
		if (ret < 0) {
			goto unlock;
		}

		if (!wait_for_rsp && !wait_for_match) {
			ret = 0;
			goto unlock;
		}

		ret = k_sem_take(&ubx->script_stopped_sem, script->timeout);
		if (ret == 0) {
			if (wait_for_rsp && script->response.received_len == 0) {
				ret = -ENOMSG;
			}
			goto unlock;
		}
	}

	ret = -ETIMEDOUT;

unlock:
	modem_ubx_unlock_script(ubx);
	return ret;
}

int modem_ubx_attach(struct modem_ubx *ubx, struct modem_pipe *pipe)
{
	if (ubx->pipe != NULL) {
		return -EALREADY;
	}

	modem_ubx_reset_parser(ubx);

	modem_pipe_attach(pipe, modem_ubx_pipe_callback, ubx);
	ubx->pipe = pipe;

	return 0;
}

void modem_ubx_release(struct modem_ubx *ubx)
{
	if (ubx->pipe == NULL) {
		return;
	}

	modem_pipe_release(ubx->pipe);
	ubx->pipe = NULL;

	(void)k_work_cancel(&ubx->receive_work);
	(void)k_work_cancel(&ubx->process_work);
	modem_ubx_reset_parser(ubx);
}

int modem_ubx_init(struct modem_ubx *ubx, const struct modem_ubx_config *config)
{
	__ASSERT_NO_MSG(ubx != NULL);
	__ASSERT_NO_MSG(config != NULL);
	__ASSERT_NO_MSG(config->receive_buf != NULL);
	__ASSERT_NO_MSG(config->receive_buf_size > 0);

	memset(ubx, 0x00, sizeof(*ubx));
	ubx->user_data = config->user_data;

	ubx->unsol_matches.array = config->unsol_matches.array;
	ubx->unsol_matches.size = config->unsol_matches.size;

	ring_buf_init(&ubx->receive_rb, config->receive_buf_size, config->receive_buf);
	k_work_init(&ubx->receive_work, modem_ubx_receive_work_handler);
	k_work_init(&ubx->process_work, modem_ubx_process_work_handler);
	k_sem_init(&ubx->script_stopped_sem, 0, 1);
	k_mutex_init(&ubx->script_run_lock);

	return 0;
}
